-- ─────────────────────────────────────────────────────────────────────
-- THE LEVEL I TEACHING-SUPPORT LAYER — completing what expertise can give
--
-- seed-pedagogy-level-1.sql established that four of the five evidence
-- states can be filled without a classroom, and filled 27 expertise
-- fields across the level. That was enough to prove the distinction and
-- not enough to teach from: four of the nineteen lessons carried real
-- teaching support and fifteen carried none, so a Teacher's Companion
-- built on it would have been a book with holes on most of its pages.
--
-- This file finishes the layer. Every one of the nineteen Level I
-- teaching lessons now carries the same eight fields:
--
--   alternative_explanation  the second way in, for when the first fails
--   analogy                  a concrete comparison a beginner can hold
--   visual_explanation       what goes on the board, and why that shape
--   differentiate_down       the smaller version for the learner behind
--   stretch                  the harder version for the learner ahead
--   intervention             what to do the moment it is not working
--   faster_explanation       the short route for a group that has it
--   remediation              how to repair the error weeks later
--
-- 19 lessons x 8 fields = 152. 27 existed; 125 are added here.
--
-- ── WHAT KIND OF KNOWLEDGE THIS IS ──
--
-- educational_expertise, every row. These are designed judgements by
-- the people who wrote the curriculum: defensible, arguable, and
-- improvable by the first qualified teacher who tries one and finds
-- better. They are NOT observation. Nothing here reports what happened
-- in a room, because nothing has happened in a room — the College has
-- taught nobody, and observed_in_teaching stays empty until it has.
--
-- The distinction is load-bearing rather than decorative. A teacher
-- reading "put the four greetings against a clock face" is reading a
-- proposal from a curriculum designer, not a finding from a classroom,
-- and is entitled to know which. tests/teaching-expertise.test.mjs
-- fails the build if any row here claims otherwise.
--
-- ── WHY THESE EIGHT AND NOT MORE ──
--
-- extension_challenge duplicates stretch, and misconceptions duplicates
-- common_mistakes and confusable_concepts, both of which are DERIVED
-- from the self-check traps and vocabulary cautions rather than
-- written. Adding either would create a second version of a field that
-- already exists and could drift from it. Eight is what a teacher
-- opening a lesson actually reaches for.
--
-- ── WHY THIS IS AN UPSERT AND NOT AN INSERT ──
--
-- seed-pedagogy.sql already creates a row for every (learning item,
-- field) pair in the programme — 1,938 of them — with value NULL and
-- evidence_state 'not_yet_evidenced'. The empty record is the record.
-- Nothing here is a new row; every statement below FILLS one that has
-- been sitting empty, which is why the totals do not move and only the
-- evidence states do.
--
-- Written first as INSERT OR IGNORE, which silently did nothing at all:
-- all 125 collided with the placeholder on the UNIQUE constraint and
-- were skipped, and the seed reported success while changing not one
-- field. The upsert below is the form seed-pedagogy-level-1.sql already
-- uses, and tests/teaching-expertise.test.mjs now counts filled fields
-- rather than trusting the file to have run.
--
-- The 27 entries already authored are not restated here, so this file
-- cannot overwrite them. Anything it does touch was NULL.
-- ─────────────────────────────────────────────────────────────────────

INSERT INTO pedagogy_entries (id, learning_item_id, field_key, value, evidence_state, source) VALUES

-- ── Lesson 1.1 — Hello! Introducing Yourself ────────────────────────
('ped_itm_l1_m1_lesson1_alternative_explanation', 'itm_l1_m1_lesson1', 'alternative_explanation', 'If "My name is" and "I''m" keep merging into "I''m name is", stop presenting them as alternatives and teach one of them only for a week. The blend is caused by offering a choice before either form is automatic; the second form is nearly free once the first is.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m1_lesson1_analogy', 'itm_l1_m1_lesson1', 'analogy', 'Two doors into the same room. Either one takes you in; a learner trying to walk through both at once produces "I''m name is".', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m1_lesson1_visual_explanation', 'itm_l1_m1_lesson1', 'visual_explanation', 'Write the two forms on separate lines, never on one line joined by a slash or the word "or". The join is the thing learners copy, and it is the join that produces the error.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m1_lesson1_faster_explanation', 'itm_l1_m1_lesson1', 'faster_explanation', 'A group that already greets confidently needs only the alphabet and the spell-back check. Take the greetings in the register rather than as a presentation stage and spend the time on spelling instead.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m1_lesson1_remediation', 'itm_l1_m1_lesson1', 'remediation', 'The blend returns under pressure weeks later, in roleplay rather than in exercises. Repair it where it appears: ask for the sentence again, slowly, and let the learner hear the doubled verb themselves rather than being told.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 1.2 — Where Are You From? ────────────────────────────────
('ped_itm_l1_m1_lesson2_alternative_explanation', 'itm_l1_m1_lesson2', 'alternative_explanation', 'If the country/nationality pairs will not stick as pairs, teach them as a sentence frame instead: "I''m from ___ . I''m ___ ." The second blank is then constrained by the first, and the pair is learned as a consequence rather than as a list.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m1_lesson2_analogy', 'itm_l1_m1_lesson2', 'analogy', 'The article before a country name is like the article in a person''s title: it belongs to a few names and not to most, and no rule predicts which. The United Kingdom keeps its "the" for the same reason the Netherlands does — the name is a description, not a label.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m1_lesson2_visual_explanation', 'itm_l1_m1_lesson2', 'visual_explanation', 'Two columns on the board, COUNTRY and NATIONALITY, and a third narrow column on the left holding only "the" with three entries in it. Three exceptions visibly outnumbered is the memorable shape; a rule with exceptions buried in it is not.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m1_lesson2_differentiate_down', 'itm_l1_m1_lesson2', 'differentiate_down', 'Let the learner answer with the country alone. "Brazil" is a complete answer to "Where are you from?" in real speech, and the full sentence can be added once the question is being understood reliably.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m1_lesson2_stretch', 'itm_l1_m1_lesson2', 'stretch', 'Ask for the difference between "I''m from Lagos" and "I live in London" for a learner who is both. The distinction between origin and residence is real, useful immediately, and prepares the past/present contrast of Module 7.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m1_lesson2_intervention', 'itm_l1_m1_lesson2', 'intervention', 'When a learner supplies a nationality where a country was asked for, do not correct the word — repeat the question with heavier stress on "from". The error is in parsing the question, and correcting the answer leaves the parsing untouched.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m1_lesson2_faster_explanation', 'itm_l1_m1_lesson2', 'faster_explanation', 'Give the three "the" countries as a closed list to be memorised, state that everything else takes no article, and move to practice. The pattern does not reward explanation and the time is better spent on production.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m1_lesson2_remediation', 'itm_l1_m1_lesson2', 'remediation', 'A wrong article on a country name is worth correcting once and then leaving. It never obscures meaning, and at this level a learner who is corrected on it repeatedly stops volunteering where they are from at all.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 2.1 — There Is / There Are ───────────────────────────────
('ped_itm_l1_m2_lesson1_alternative_explanation', 'itm_l1_m2_lesson1', 'alternative_explanation', 'If agreement will not settle, teach the learner to look one word to the right of the verb and nowhere else. "There" is a placeholder and tells them nothing; the noun immediately after the verb decides the form, every time.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson1_analogy', 'itm_l1_m2_lesson1', 'analogy', '"There" is the doorway, not the thing in the room. You do not describe a doorway as one or many — you describe what is standing in it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson1_visual_explanation', 'itm_l1_m2_lesson1', 'visual_explanation', 'Draw the sentence as three boxes: THERE | IS/ARE | NOUN, with an arrow from the third box back to the second and none from the first. The missing arrow is the teaching point.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson1_differentiate_down', 'itm_l1_m2_lesson1', 'differentiate_down', 'Restrict the practice to singular only for the first round, so word order can be learned without agreement competing for attention. Introduce the plural once "Is there a...?" is reliable.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson1_stretch', 'itm_l1_m2_lesson1', 'stretch', 'Ask for a description of a room the learner cannot see — the corridor outside, or the room next door — so the structure has to be used from memory rather than read off the walls.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson1_intervention', 'itm_l1_m2_lesson1', 'intervention', 'When the question comes out as "There is a window?" with rising intonation, the learner has the meaning and is missing only the inversion. Model the question form and have them repeat it immediately, before the statement version sets.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson1_faster_explanation', 'itm_l1_m2_lesson1', 'faster_explanation', 'One "there is", one "there are", one negative and one question, then straight into describing the classroom they are sitting in. The structure is transparent and over-explaining it costs practice time it does not repay.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson1_remediation', 'itm_l1_m2_lesson1', 'remediation', 'Uninverted questions persist. When one appears later, ask the learner to write the sentence and then physically swap the first two words with their finger. The move is what is being learned, not the rule.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 2.2 — This, That, These, Those ───────────────────────────
('ped_itm_l1_m2_lesson2_alternative_explanation', 'itm_l1_m2_lesson2', 'alternative_explanation', 'If the four-way grid confuses, split it into two separate decisions taken in order: near or far first, one or many second. Learners who fail the grid usually succeed at both questions asked one at a time.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson2_analogy', 'itm_l1_m2_lesson2', 'analogy', 'Two questions the word answers before it is spoken: how far, and how many. English packs both answers into one word, which is why a language that packs only one feels short of a word here.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson2_visual_explanation', 'itm_l1_m2_lesson2', 'visual_explanation', 'A two-by-two grid drawn on the floor with tape or chalk, not on the board — NEAR and FAR as physical distance from where the learner stands, SINGULAR and PLURAL as the columns. Distance taught at a distance is remembered.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson2_differentiate_down', 'itm_l1_m2_lesson2', 'differentiate_down', 'Teach "this" and "these" alone until they are secure. A learner who defaults to "this" for everything is understood perfectly well, and the far pair can wait a lesson.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson2_stretch', 'itm_l1_m2_lesson2', 'stretch', 'Ask them to use the pair where distance is not physical: "this week" against "that year". The metaphorical extension is how the words actually behave in adult speech and it is available at this level.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson2_intervention', 'itm_l1_m2_lesson2', 'intervention', 'When "this" is used for everything, stop asking for the word and start asking the learner to point first. The gesture forces the distance decision, and the word follows the gesture more readily than it follows a rule.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson2_faster_explanation', 'itm_l1_m2_lesson2', 'faster_explanation', 'Hold up one object near, one far, two near, two far, naming each. Four gestures and four words, then practice. Groups whose first language marks distance need no more than this.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m2_lesson2_remediation', 'itm_l1_m2_lesson2', 'remediation', 'The default to "this" outlasts the module. Correct it only where distance carries meaning — pointing at two different shops — and let it stand where it does not, or the correction costs more fluency than the error costs clarity.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 3.1 — My Family ──────────────────────────────────────────
('ped_itm_l1_m3_lesson1_alternative_explanation', 'itm_l1_m3_lesson1', 'alternative_explanation', 'If the short answer keeps coming out as "Yes, I have", teach it as an echo rather than as a rule: whatever word started the question comes back in the answer. "Do you...?" returns "I do". The echo is audible and the rule is not.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m3_lesson1_analogy', 'itm_l1_m3_lesson1', 'analogy', 'The short answer is a ball thrown back. The question throws "do"; the answer has to return the same ball, not a different one.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m3_lesson1_visual_explanation', 'itm_l1_m3_lesson1', 'visual_explanation', 'A family tree drawn on the board with the learner at the centre rather than at the bottom. Terms radiate outward from a person who is present, which is how the vocabulary will actually be used.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m3_lesson1_differentiate_down', 'itm_l1_m3_lesson1', 'differentiate_down', 'Six terms rather than eight, and the immediate family only. Grandparents and cousins can be added the following week without disturbing anything already learned.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m3_lesson1_stretch', 'itm_l1_m3_lesson1', 'stretch', 'Ask for a family described in the third person — a friend''s family rather than their own. It forces the possessive away from "my" and previews the his/her work of Module 6.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m3_lesson1_intervention', 'itm_l1_m3_lesson1', 'intervention', 'Family is not neutral ground. If a learner goes quiet at this topic, switch the task to a family they invent or a family from the listening text, and do not ask why. The grammar is the objective; the biography is not.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m3_lesson1_faster_explanation', 'itm_l1_m3_lesson1', 'faster_explanation', 'The vocabulary is largely transparent to learners with any European first language. Check the four that are not — cousin, children, parents, siblings — and give the time to the short-answer drill instead.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m3_lesson1_remediation', 'itm_l1_m3_lesson1', 'remediation', 'The incomplete short answer is worth returning to because it is not a family error — it is the auxiliary system, and it will reappear in Modules 7 and 8. Repair it there, in the past and future forms, rather than treating each as new.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 3.2 — My Day (completing the set) ────────────────────────
('ped_itm_l1_m3_lesson2_faster_explanation', 'itm_l1_m3_lesson2', 'faster_explanation', 'Give the third-person -s as a single rule with no exceptions worth mentioning at this level, and spend the recovered time on the clock. Telling the time is the harder half of this lesson and is routinely under-practised because the grammar looks more teachable.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m3_lesson2_remediation', 'itm_l1_m3_lesson2', 'remediation', 'This is the error that persists for months, and re-teaching it does not work because it is already known. Repair it by narrowing the demand: for one task, correct nothing except the missing -s, and tell the learner that is the only thing being listened for.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 4.1 — Countable & Uncountable ────────────────────────────
('ped_itm_l1_m4_lesson1_alternative_explanation', 'itm_l1_m4_lesson1', 'alternative_explanation', 'If the countable/uncountable split will not settle, drop the categories and teach the test instead: can you put a number directly in front of it? Three apples, yes. Three rices, no. The label matters less than the test, and the test transfers to words never taught.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m4_lesson1_visual_explanation', 'itm_l1_m4_lesson1', 'visual_explanation', 'Two containers drawn on the board: a basket holding separate shapes, and a jug holding one continuous mass. Sort the food words into the pictures rather than into two word-lists — the picture predicts new words, the list does not.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m4_lesson1_differentiate_down', 'itm_l1_m4_lesson1', 'differentiate_down', 'Work with countable nouns and "some" only. A learner who says "some rice" and "some apples" is understood everywhere, and the any/questions half can be taken in the following lesson without loss.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m4_lesson1_faster_explanation', 'itm_l1_m4_lesson1', 'faster_explanation', 'State the number test, state some/any, name the polite-offer exception once, and go to the market roleplay. The category is intuitive for most food words and the exceptions are what need airtime.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m4_lesson1_remediation', 'itm_l1_m4_lesson1', 'remediation', 'The words that stay wrong are the ones that are countable in the learner''s first language and not in English — bread, advice, furniture, information. Keep a running list on the wall and add to it as they surface, rather than pre-teaching a list nobody has needed yet.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 4.2 — At the Shop ────────────────────────────────────────
('ped_itm_l1_m4_lesson2_alternative_explanation', 'itm_l1_m4_lesson2', 'alternative_explanation', 'If "How much are these?" keeps becoming "How many", separate the two questions by what they want back. "How much" wants money; "how many" wants a number of things. The learner is not choosing between grammar forms, they are choosing between answers.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m4_lesson2_analogy', 'itm_l1_m4_lesson2', 'analogy', '"How much" is the question you ask the till, not the shelf. The till only ever answers in money, however many things you put on it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m4_lesson2_visual_explanation', 'itm_l1_m4_lesson2', 'visual_explanation', 'Real or drawn price tags on real objects, with the question written above them. Prices read off a tag are read the way they are spoken; prices read off a board are read as numbers.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m4_lesson2_differentiate_down', 'itm_l1_m4_lesson2', 'differentiate_down', 'Fix the request at one form — "Can I have..., please?" — and drop the singular/plural variation in the question. A learner who can ask for something politely and understand the price has the transaction.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m4_lesson2_stretch', 'itm_l1_m4_lesson2', 'stretch', 'Give them a fixed budget and a shopping list that does not fit inside it. The negotiation that follows produces comparatives and "too expensive" naturally, ahead of where they are taught.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m4_lesson2_intervention', 'itm_l1_m4_lesson2', 'intervention', 'When "I want" appears, do not label it rude — say what it sounds like and give the replacement in the same breath. Learners who are told a form is rude often stop speaking rather than switch forms.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m4_lesson2_faster_explanation', 'itm_l1_m4_lesson2', 'faster_explanation', 'The language is short and the difficulty is in hearing prices at speed. Skip the presentation, run the roleplay early, and use the remaining time for listening to spoken amounts.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m4_lesson2_remediation', 'itm_l1_m4_lesson2', 'remediation', 'Understanding a spoken price is the part that fails outside the classroom, not producing the question. Return to it with recorded amounts rather than with the grammar, which is usually already secure.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 5.1 — Prepositions of Place ──────────────────────────────
('ped_itm_l1_m5_lesson1_alternative_explanation', 'itm_l1_m5_lesson1', 'alternative_explanation', 'If "opposite" and "next to" keep swapping, define them by what has to be between the two things. Next to: nothing. Opposite: a road. The gap is the difference, and it is visible.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m5_lesson1_analogy', 'itm_l1_m5_lesson1', 'analogy', 'Next to is shoulder to shoulder. Opposite is face to face. Between needs two other people to stand still.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m5_lesson1_visual_explanation', 'itm_l1_m5_lesson1', 'visual_explanation', 'Arrange the learners themselves rather than drawing a map: three standing in a line, two facing each other across the room. The preposition describes the arrangement they are in, and they can feel which one applies.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m5_lesson1_differentiate_down', 'itm_l1_m5_lesson1', 'differentiate_down', 'Four prepositions rather than six, and leave out "opposite" and "between" — the two that need a second reference point. In, on, under and next to describe most of what a beginner needs to locate.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m5_lesson1_stretch', 'itm_l1_m5_lesson1', 'stretch', 'Have them describe a location without naming the place, for a partner to identify. Description under a constraint produces far more preposition use than a labelling task does.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m5_lesson1_intervention', 'itm_l1_m5_lesson1', 'intervention', 'When "between" appears with one place, the missing element is "and", not the preposition. Supply the frame — between ___ and ___ — with two blanks visible, and the error corrects itself.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m5_lesson1_faster_explanation', 'itm_l1_m5_lesson1', 'faster_explanation', 'Most of these map one-to-one onto other languages. Check "opposite" and "between", assume the rest, and use the time for the map task, which is where the real work is.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m5_lesson1_remediation', 'itm_l1_m5_lesson1', 'remediation', 'Preposition errors at this level rarely block meaning and rarely repay correction in the moment. Note which pair a learner confuses and rebuild it in the next map task rather than interrupting speech.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 5.2 — Giving Directions ──────────────────────────────────
('ped_itm_l1_m5_lesson2_alternative_explanation', 'itm_l1_m5_lesson2', 'alternative_explanation', 'If the imperative keeps acquiring a subject — "You go straight on" — teach it as the form used on signs. Signs have no room for "you", and learners have seen hundreds of them.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m5_lesson2_analogy', 'itm_l1_m5_lesson2', 'analogy', '"Excuse me" is the knock before the door opens. The question without it is not ruder in grammar, it simply arrives without warning.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m5_lesson2_differentiate_down', 'itm_l1_m5_lesson2', 'differentiate_down', 'Three directions only — straight on, left, right — and no distance. A learner who can give three instructions in sequence has the communicative goal; crossing and distance can wait.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m5_lesson2_faster_explanation', 'itm_l1_m5_lesson2', 'faster_explanation', 'The imperatives are few and transparent. Present them in one minute and put the whole lesson into the listening half, where following a spoken sequence at natural speed is genuinely difficult.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m5_lesson2_remediation', 'itm_l1_m5_lesson2', 'remediation', 'What fails later is following directions, not giving them. Return to this with audio rather than with roleplay, because a partner speaking slowly is not the condition the learner will meet.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 6.1 — Describing People ──────────────────────────────────
('ped_itm_l1_m6_lesson1_alternative_explanation', 'itm_l1_m6_lesson1', 'alternative_explanation', 'If "She has tall" persists, sort the adjectives by what they attach to rather than by meaning: words describing the whole person take BE, words describing a part the person owns take HAVE. Tall is the person; hair is a possession.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson1_analogy', 'itm_l1_m6_lesson1', 'analogy', 'BE is what you are; HAVE is what you carry. You are tall. You carry brown eyes and a pair of glasses.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson1_visual_explanation', 'itm_l1_m6_lesson1', 'visual_explanation', 'One figure on the board with two colours of label: whole-person labels attached to the outline, part-labels attached by an arrow to the part. The two attachment points are the grammar.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson1_stretch', 'itm_l1_m6_lesson1', 'stretch', 'Ask for a description precise enough that a partner can pick the person out of a photograph of a crowd. The precision requirement produces the adjective ordering of Lesson 6.2 before it is taught.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson1_faster_explanation', 'itm_l1_m6_lesson1', 'faster_explanation', 'Give the BE/HAVE split as two example sentences, check "look like" against "look", and move to describing people in the room. The vocabulary is concrete and does not need presenting.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson1_remediation', 'itm_l1_m6_lesson1', 'remediation', 'Describing people invites personal remarks. When repairing this later, use photographs of strangers rather than classmates — it keeps the correction about grammar and avoids a learner being described unflatteringly in front of the room.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 6.2 — Possessives ────────────────────────────────────────
('ped_itm_l1_m6_lesson2_alternative_explanation', 'itm_l1_m6_lesson2', 'alternative_explanation', 'If my/mine will not separate, use the noun as the test rather than the meaning: if a noun follows, the short word goes in; if nothing follows, the long word does. My book. It''s mine. The learner can apply that without understanding the terms.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson2_analogy', 'itm_l1_m6_lesson2', 'analogy', '"My" is a label stuck on something. "Mine" is what you say when the thing has already been pointed at and needs no label.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson2_visual_explanation', 'itm_l1_m6_lesson2', 'visual_explanation', 'Two columns with a deliberate blank: WITH A NOUN and ALONE. Write "his" in both, and leave the visible oddity unexplained until a learner notices it. The one word that breaks the pattern is remembered by being caught, not by being announced.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson2_differentiate_down', 'itm_l1_m6_lesson2', 'differentiate_down', 'Possessive adjectives only. A learner who can say "my bag, her coat, their car" has what the level needs; the pronoun set is a refinement and can be dropped without cost.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson2_stretch', 'itm_l1_m6_lesson2', 'stretch', 'Collect objects, mix them, and run the return as a whole-class task requiring "Whose is this?" and a pronoun answer. The pronoun is only natural where the noun is already obvious, which a list exercise cannot create.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson2_intervention', 'itm_l1_m6_lesson2', 'intervention', 'When "her''s" is written, the learner has generalised the possessive apostrophe correctly and applied it one step too far. Say that first. A correct generalisation misapplied deserves different handling from a random error.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson2_faster_explanation', 'itm_l1_m6_lesson2', 'faster_explanation', 'One example pair, the "his" oddity, the no-apostrophe warning, then the object-return activity. The system is small and the practice is what fixes it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m6_lesson2_remediation', 'itm_l1_m6_lesson2', 'remediation', 'The apostrophe in "her''s" and "their''s" returns in written work for months. Correct it in writing only — it is inaudible in speech, and interrupting speech for an error nobody can hear costs fluency for nothing.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 7.1 — Regular Past Verbs ─────────────────────────────────
('ped_itm_l1_m7_lesson1_alternative_explanation', 'itm_l1_m7_lesson1', 'alternative_explanation', 'If the -ed spelling changes will not stick, teach only the y-rule and let the doubling go. The doubled consonant affects few verbs at this level, and a learner spelling "stoped" is understood; a learner paralysed by two spelling rules stops writing.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m7_lesson1_visual_explanation', 'itm_l1_m7_lesson1', 'visual_explanation', 'Three columns headed by the three sounds of -ed rather than by spelling: /t/, /d/, /ɪd/. Sorting by sound explains why "visited" gains a syllable and "played" does not, which the spelling alone never will.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m7_lesson1_differentiate_down', 'itm_l1_m7_lesson1', 'differentiate_down', 'Six verbs, all of them regular with no spelling change, and positives only. Adding "didn''t" doubles the load, and it is the negative that removes the -ed — the exact thing that confuses.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m7_lesson1_stretch', 'itm_l1_m7_lesson1', 'stretch', 'Ask for a short account of yesterday in which every verb is regular. The constraint forces vocabulary choice and makes the irregular verbs of Lesson 7.2 feel needed rather than imposed.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m7_lesson1_remediation', 'itm_l1_m7_lesson1', 'remediation', 'The -ed surviving after "didn''t" is the durable error, and it lasts weeks because it is logical — the learner is marking the past twice. Name that logic when repairing it: the auxiliary has already carried the tense, so the verb does not have to.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 7.2 — Irregular Past Verbs & Questions ───────────────────
('ped_itm_l1_m7_lesson2_alternative_explanation', 'itm_l1_m7_lesson2', 'alternative_explanation', 'If "Where did you went?" persists, teach the question as a fixed opening rather than a construction: "Did you" and "What did you" are chunks, and whatever follows them is the plain verb. Chunking beats analysis while the irregular forms are still being learned.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m7_lesson2_analogy', 'itm_l1_m7_lesson2', 'analogy', 'Only one word in the sentence is allowed to carry the past. Once "did" has taken it, the main verb puts it down.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m7_lesson2_visual_explanation', 'itm_l1_m7_lesson2', 'visual_explanation', 'Write the statement above the question with the tense marker circled in each, and draw a line showing it move leftward onto "did". One mark, two positions.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m7_lesson2_differentiate_down', 'itm_l1_m7_lesson2', 'differentiate_down', 'Yes/no questions only, and six irregular verbs. Wh- questions add a second variable at the front of a sentence whose back half is not yet secure.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m7_lesson2_intervention', 'itm_l1_m7_lesson2', 'intervention', 'When the double past appears, do not correct the sentence — repeat it back as a question with heavy stress on "did", and wait. Most learners self-correct within two seconds, and a self-correction holds better than a supplied one.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m7_lesson2_faster_explanation', 'itm_l1_m7_lesson2', 'faster_explanation', 'State the one rule — after "did", the base form — give the irregular list as vocabulary to be memorised rather than taught, and spend the lesson narrating weekends.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m7_lesson2_remediation', 'itm_l1_m7_lesson2', 'remediation', 'Irregular forms and the question rule fail independently and need repairing separately. A learner who says "Did you went" knows the irregular form perfectly; a learner who says "Did you goed" does not. The correction is different in each case.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 8.1 — Can / Ability ──────────────────────────────────────
('ped_itm_l1_m8_lesson1_analogy', 'itm_l1_m8_lesson1', 'analogy', '"Can" is already holding the verb''s hand. There is no room for "to" between them.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson1_visual_explanation', 'itm_l1_m8_lesson1', 'visual_explanation', 'Write "can" and the verb touching, with no gap, against a second line showing "want to" with the "to" boxed. Seeing the two patterns side by side is what stops the transfer.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson1_differentiate_down', 'itm_l1_m8_lesson1', 'differentiate_down', 'Positive statements and short answers only. "Can''t" is hard to hear and hard to say, and a learner who can state abilities and answer questions has the lesson''s communicative purpose.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson1_stretch', 'itm_l1_m8_lesson1', 'stretch', 'Ask for degrees rather than absolutes — "a little", "quite well", "not very well". Ability is rarely binary in real speech, and the hedges are available at this level.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson1_intervention', 'itm_l1_m8_lesson1', 'intervention', 'When "she cans" appears, the learner is applying the third-person -s correctly and to the wrong class of verb. Say so. Modals are the exception, and framing it as an exception protects the rule they have just spent Module 3 learning.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson1_faster_explanation', 'itm_l1_m8_lesson1', 'faster_explanation', 'One form for every subject, no "to" after it, and the negative is one word. Three sentences of presentation, then the survey activity.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson1_remediation', 'itm_l1_m8_lesson1', 'remediation', 'The "to" after a modal returns when learners meet "have to" and "want to" in the same week. Repair it by contrast rather than by rule: put the three side by side and let the learner sort which take "to".', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 8.2 — Going To / Plans ───────────────────────────────────
('ped_itm_l1_m8_lesson2_alternative_explanation', 'itm_l1_m8_lesson2', 'alternative_explanation', 'If "going to go" sounds wrong to learners and they drop one of them, confirm that their ear is right and the form is still correct. The repetition is genuinely odd, and telling a learner their instinct is sound buys more than telling them the rule again.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson2_analogy', 'itm_l1_m8_lesson2', 'analogy', '"Going to" is a decision already taken, walking toward the thing. "Can" is only a statement about what is possible — nobody has set off yet.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson2_visual_explanation', 'itm_l1_m8_lesson2', 'visual_explanation', 'A timeline with NOW marked and an arrow forward, and the plan written at the far end. Then a second line with no arrow at all for "can". The presence and absence of the arrow is the distinction.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson2_differentiate_down', 'itm_l1_m8_lesson2', 'differentiate_down', 'First person only — "I''m going to" — and no questions. The auxiliary agreement is a separate difficulty and the plan-making is the point of the lesson.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson2_stretch', 'itm_l1_m8_lesson2', 'stretch', 'Ask them to distinguish a plan from a prediction: what they are going to do at the weekend, and what they think the weather is going to do. Both use the form and only one is a decision.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson2_faster_explanation', 'itm_l1_m8_lesson2', 'faster_explanation', 'The form is transparent once "am/is/are" is secure. Check the auxiliary, name the plan-versus-ability contrast in one example pair, and run the weekend-plans activity.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m8_lesson2_remediation', 'itm_l1_m8_lesson2', 'remediation', 'The dropped auxiliary — "I going to study" — is the error that lasts, and it is a "be" problem rather than a future problem. Repair it wherever "be" is weak, not only in future sentences.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 9.1 — Body & Health ──────────────────────────────────────
('ped_itm_l1_m9_lesson1_alternative_explanation', 'itm_l1_m9_lesson1', 'alternative_explanation', 'If have and feel keep swapping, split them by what follows rather than by meaning: HAVE takes a thing you could name to a doctor — a headache, a cold, a temperature. FEEL takes a word describing you — tired, sick, better.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson1_analogy', 'itm_l1_m9_lesson1', 'analogy', 'You have the illness the way you have a bag — it is a thing, and you could put it down. You feel the way you feel, and there is nothing to put down.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson1_visual_explanation', 'itm_l1_m9_lesson1', 'visual_explanation', 'A body outline with the problems written as labels pointing at parts, and the feelings written in a separate box beside it with no arrows. Problems have a location; feelings do not.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson1_differentiate_down', 'itm_l1_m9_lesson1', 'differentiate_down', 'Six body parts and three problems. A learner who can say where it hurts has what the lesson exists for, and the feelings vocabulary can follow separately.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson1_stretch', 'itm_l1_m9_lesson1', 'stretch', 'Ask how long the problem has lasted — "I have had a headache since yesterday", "I have had a cold for two days". Duration is what a real consultation asks next, and it gives an early, purposeful reason to reach past the present tense.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson1_faster_explanation', 'itm_l1_m9_lesson1', 'faster_explanation', 'Body vocabulary can be checked by pointing in under two minutes. Give the time to the have/feel split, which is the only part of this lesson that resists.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson1_remediation', 'itm_l1_m9_lesson1', 'remediation', '"I am headache" is worth repairing properly, because it is the same be/have confusion that produced "she has tall" in Module 6. Treat the two together — a learner who sees the pattern once fixes both.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Lesson 9.2 — Should / Advice ────────────────────────────────────
('ped_itm_l1_m9_lesson2_alternative_explanation', 'itm_l1_m9_lesson2', 'alternative_explanation', 'If "should to" appears, do not re-teach modals — point back to "can" from Lesson 8.1. Learners who have met one modal recognise the class faster than they absorb a new rule about it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson2_analogy', 'itm_l1_m9_lesson2', 'analogy', 'Advice is handed over, not thrown. The response is picking it up — even a short one. Saying nothing looks, in English, like leaving it on the floor.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson2_visual_explanation', 'itm_l1_m9_lesson2', 'visual_explanation', 'Two columns, PROBLEM and ADVICE, joined by learners drawing the lines themselves. The pairing is the reasoning task; a pre-joined table removes the only thinking in the lesson.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson2_differentiate_down', 'itm_l1_m9_lesson2', 'differentiate_down', '"You should" only, with "shouldn''t" left out. Positive advice covers the communicative need, and the negative can be added once the form is automatic.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson2_intervention', 'itm_l1_m9_lesson2', 'intervention', 'When advice is met with silence, the learner has usually understood and has no phrase ready. Supply two — "That''s a good idea" and "Thank you, I will" — and put them on the board before the roleplay rather than after it fails.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson2_faster_explanation', 'itm_l1_m9_lesson2', 'faster_explanation', 'Same form for every subject, base verb after it, and two response phrases. Then straight into the problem-and-advice pairing, which is where the lesson earns its time.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m9_lesson2_remediation', 'itm_l1_m9_lesson2', 'remediation', 'What needs returning to is not the grammar but the response. Learners who have not internalised that English advice expects acknowledgement read as dismissive in every later roleplay, and the cost compounds well beyond this lesson.', 'educational_expertise', 'Designed by the curriculum authors.'),

-- ── Revision Lesson — Structured Consolidation ──────────────────────
('ped_itm_l1_m10_revlesson_alternative_explanation', 'itm_l1_m10_revlesson', 'alternative_explanation', 'If learners can produce each structure on demand but not choose between them, stop revising structures and start revising situations. Give the context and ask which form it needs — selection is the skill being assessed, and drilling forms does not build it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m10_revlesson_analogy', 'itm_l1_m10_revlesson', 'analogy', 'Nine modules have given them nine tools. The exam does not ask whether they own a hammer; it puts a nail in front of them and says nothing.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m10_revlesson_visual_explanation', 'itm_l1_m10_revlesson', 'visual_explanation', 'One wall chart, nine boxes, one example sentence in each — built by the class rather than supplied. What the learners cannot fill in is the revision list, and it is more accurate than any diagnostic the teacher would write.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m10_revlesson_differentiate_down', 'itm_l1_m10_revlesson', 'differentiate_down', 'Narrow the revision to the three structures the learner''s own self-checks flagged rather than covering all nine thinly. Coverage is the wrong goal in the last week; security in a few is worth more in the exam.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m10_revlesson_stretch', 'itm_l1_m10_revlesson', 'stretch', 'Have them write the exam questions rather than answer them. Setting a good question requires knowing what the structure is for, which is a level above using it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_itm_l1_m10_revlesson_faster_explanation', 'itm_l1_m10_revlesson', 'faster_explanation', 'Skip the review of content entirely for a secure group and run mixed-context selection tasks for the whole session. Re-presenting known material is the commonest way a revision lesson wastes itself.', 'educational_expertise', 'Designed by the curriculum authors.')
ON CONFLICT (learning_item_id, field_key) DO UPDATE SET
  value = excluded.value, evidence_state = excluded.evidence_state, source = excluded.source;
